import type { ReactNode, Ref } from 'react';

import { FlexRender } from '@tanstack/react-table';
import { ChevronRight } from 'lucide-react';

import { CellEditor } from '@/components/data-grid/cell-editor';
import { ColumnTable } from '@/components/data-grid/column-table';
import { AggregationMark } from '@/components/data-grid/footer';
import { messages } from '@/components/data-grid/messages';
import { focusOutlineClassName, pinnedClassName, rangeShadow, textAlign } from '@/components/data-grid/styles';
import { cn } from '@/lib/utils';
import {
  useBodyCell,
  useDataRow,
  useGroupRowCell,
  useRowToggle,
  useVirtualRows,
  type BodyCellOptions,
  type CoreTable,
  type GridCell,
  type GridRow,
  type RowOptions,
} from '@istec/grid';

export interface DataRowOptions<TData extends object> extends RowOptions<TData> {
  rowClassName?: (row: GridRow<TData>) => string | undefined;
}

export function VirtualRows<TData extends object>({
  table,
  scrollElement,
  overscan,
  noRows,
  ...rowOptions
}: DataRowOptions<TData> & {
  table: CoreTable<TData>;
  scrollElement: HTMLElement | null;
  overscan: number;
  noRows?: ReactNode;
}) {
  const { rows, paddingTop, paddingBottom, sticky, colSpan, viewportWidth, measureElement, empty } = useVirtualRows(
    table,
    { scrollElement, rowHeight: rowOptions.rowHeight, overscan }
  );

  if (empty) {
    return (
      <ColumnTable table={table}>
        <tbody>
          <tr>
            <td colSpan={colSpan} className="h-24 text-center text-muted-foreground">
              {noRows ?? messages.noRows}
            </td>
          </tr>
        </tbody>
      </ColumnTable>
    );
  }

  return (
    <>
      {sticky.length > 0 && (
        <div className="sticky top-0 z-10 h-0">
          {sticky.map(({ row, top, zIndex }) => (
            <ColumnTable key={row.id} table={table} className="absolute" style={{ top, zIndex }}>
              <tbody>
                <DataRow
                  row={row}
                  {...rowOptions}
                  rowClassName={(stuck) => cn('bg-background', rowOptions.rowClassName?.(stuck))}
                />
              </tbody>
            </ColumnTable>
          ))}
        </div>
      )}
      <ColumnTable table={table}>
        <tbody>
          {paddingTop > 0 && <tr aria-hidden style={{ height: paddingTop }} />}
          {rows.map((entry) =>
            entry.kind === 'detail' ? (
              <DetailRow
                key={entry.key}
                index={entry.index}
                measureRef={measureElement}
                colSpan={colSpan}
                width={viewportWidth}
              >
                {entry.detail}
              </DetailRow>
            ) : (
              <DataRow
                key={entry.key}
                row={entry.row}
                index={entry.index}
                measureRef={measureElement}
                {...rowOptions}
              />
            )
          )}
          {paddingBottom > 0 && <tr aria-hidden style={{ height: paddingBottom }} />}
        </tbody>
      </ColumnTable>
    </>
  );
}

export function DataRow<TData extends object>({
  row,
  index,
  measureRef,
  rowClassName,
  ...options
}: DataRowOptions<TData> & { row: GridRow<TData>; index?: number; measureRef?: Ref<HTMLTableRowElement> }) {
  const { grouped, clickable, cells, groupRow, groupToggles, rowProps } = useDataRow(row, {
    ...options,
    index,
    measureRef,
  });
  const events = { onCellClick: options.onCellClick, onCellDoubleClick: options.onCellDoubleClick };

  return (
    <tr
      {...rowProps}
      className={cn(
        'group/row transition-colors hover:bg-muted/50 data-[state=selected]:bg-muted [&>td]:border-b',
        grouped && 'font-medium',
        clickable && 'cursor-pointer',
        rowClassName?.(row)
      )}
    >
      {groupRow ? (
        <>
          {groupRow.kept.map((slot) => (
            <BodyCell
              key={slot.item.id}
              cell={slot.item}
              region={slot.region}
              index={slot.index}
              edge={slot.edge}
              groupToggles={false}
            />
          ))}
          <GroupRowCell row={row} colSpan={groupRow.colSpan} stickyLeft={groupRow.stickyLeft} />
        </>
      ) : (
        cells?.map((slot) =>
          slot === 'filler' ? (
            <td key="filler" aria-hidden />
          ) : (
            <BodyCell
              key={slot.item.id}
              cell={slot.item}
              region={slot.region}
              index={slot.index}
              edge={slot.edge}
              groupToggles={groupToggles}
              {...events}
            />
          )
        )
      )}
    </tr>
  );
}

function BodyCell<TData extends object>({
  cell,
  edge,
  ...options
}: BodyCellOptions<TData> & { cell: GridCell<TData>; edge: boolean }) {
  const { look, content, shownCell, align, aggregation, toggleLevel, className, cellProps, fillHandleProps } =
    useBodyCell(cell, options);
  const editing = content === 'editor';
  const { region } = options;

  return (
    <td
      {...cellProps}
      style={{ ...cellProps.style, boxShadow: rangeShadow(look) }}
      className={cn(
        'px-2 align-middle whitespace-nowrap outline-none',
        ((look.focused && !look.inRange) || editing) && focusOutlineClassName,
        editing ? 'relative p-0' : 'truncate',
        textAlign[align],
        pinnedClassName(region, edge),
        region !== 'center' &&
          'group-hover/row:bg-[color-mix(in_oklab,--theme(--color-muted)_50%,--theme(--color-background))] group-data-[state=selected]/row:bg-muted',
        look.inRange && 'bg-[color-mix(in_oklab,--theme(--color-primary)_10%,--theme(--color-background))]',
        look.fillHandle && region === 'center' && 'relative',
        className
      )}
    >
      {content === 'editor' ? (
        <CellEditor cell={cell} />
      ) : content === 'group' || content === 'toggle' ? (
        <RowToggle row={cell.row} level={toggleLevel} showCount={content === 'group'}>
          <FlexRender cell={shownCell} />
        </RowToggle>
      ) : content === 'empty' ? null : (
        <>
          <AggregationMark aggregation={aggregation} />
          <FlexRender cell={shownCell} />
        </>
      )}
      {look.fillHandle && !editing && (
        <span
          {...fillHandleProps}
          className="absolute right-0 bottom-0 hidden size-1.5 cursor-crosshair bg-primary group-focus-within/grid:block"
        />
      )}
    </td>
  );
}

function RowToggle<TData extends object>({
  row,
  level,
  showCount = false,
  children,
}: {
  row: GridRow<TData>;
  level: number;
  showCount?: boolean;
  children: ReactNode;
}) {
  const toggle = useRowToggle(row);

  return (
    <span className="flex max-w-full items-center gap-1" style={{ paddingLeft: level * 16 }}>
      {toggle.canExpand ? (
        <button
          type="button"
          {...toggle.buttonProps}
          aria-label={toggle.expanded ? messages.collapse : messages.expand}
          className="-m-0.5 shrink-0 cursor-pointer rounded-sm p-0.5 hover:bg-muted-foreground/20"
        >
          <ChevronRight className={cn('size-3.5 transition-transform', toggle.expanded && 'rotate-90')} />
        </button>
      ) : (
        // Rows that cannot expand keep the toggle's space, so the content of a level lines up.
        <span aria-hidden className="size-3.5 shrink-0" />
      )}
      <span className="truncate">{children}</span>
      {showCount && <span className="text-muted-foreground tabular-nums">({toggle.count})</span>}
    </span>
  );
}

function DetailRow({
  index,
  measureRef,
  colSpan,
  width,
  children,
}: {
  index: number;
  measureRef: Ref<HTMLTableRowElement>;
  colSpan: number;
  width: number | undefined;
  children: ReactNode;
}) {
  return (
    <tr data-index={index} ref={measureRef} className="[&>td]:border-b">
      <td data-row-detail colSpan={colSpan} className="overflow-clip bg-muted/30 p-0">
        <div className="sticky left-0 p-3 whitespace-normal" style={{ width }}>
          {children}
        </div>
      </td>
    </tr>
  );
}

function GroupRowCell<TData extends object>({
  row,
  colSpan,
  stickyLeft,
}: {
  row: GridRow<TData>;
  colSpan: number;
  stickyLeft: number;
}) {
  const { cell, focused, label, cellProps } = useGroupRowCell(row);

  return (
    // Clipped rather than hidden: a hidden overflow would capture the sticky label below.
    <td
      {...cellProps}
      colSpan={colSpan}
      className={cn('overflow-clip px-2 align-middle whitespace-nowrap outline-none', focused && focusOutlineClassName)}
    >
      <div className="sticky w-fit" style={{ left: stickyLeft + 8 }}>
        {cell && (
          <RowToggle row={row} level={row.depth} showCount>
            <span className="font-normal text-muted-foreground">{label}: </span>
            <FlexRender cell={cell} />
          </RowToggle>
        )}
      </div>
    </td>
  );
}

import { Check } from 'lucide-react';

import { editorErrorText, messages } from '@/components/data-grid/messages';
import { Popover, PopoverContent } from '@/components/ui/popover';
import { cn } from '@/lib/utils';
import { useCellEditor, useVirtualList, type CellEditorModel, type GridCell } from '@istec/grid';

const inputClassName = 'h-full w-full min-w-0 bg-background px-2 text-xs outline-none';

export function CellEditor<TData extends object>({ cell }: { cell: GridCell<TData> }) {
  const editor = useCellEditor(cell);
  const { kind, custom, error, input, inputProps } = editor;

  if (custom !== undefined) return <div className="h-full w-full">{custom}</div>;

  return (
    <>
      <input
        {...inputProps}
        aria-label={messages.editValue}
        className={cn(inputClassName, kind === 'number' && 'text-right')}
      />
      {kind === 'select' && (
        <Popover open>
          <PopoverContent
            anchor={input}
            align="start"
            initialFocus={false}
            finalFocus={false}
            className="w-auto min-w-48 gap-0 p-1"
          >
            <ChoiceList editor={editor} />
          </PopoverContent>
        </Popover>
      )}
      {error !== undefined && (
        <div
          role="alert"
          className="absolute top-full left-0 z-30 mt-0.5 rounded-sm bg-destructive px-2 py-1 whitespace-nowrap text-white shadow-sm"
        >
          {editorErrorText(error)}
        </div>
      )}
    </>
  );
}

function ChoiceList({ editor: { choices, activeIndex, listProps, choiceProps } }: { editor: CellEditorModel }) {
  const list = useVirtualList(choices.length, { itemHeight: 28, maxHeight: 280, activeIndex });

  return (
    <div {...listProps} {...list.scrollProps}>
      <div style={list.contentStyle}>
        {list.items.map((item) => {
          const choice = choices[item.index];
          if (!choice) return null;
          return (
            <div
              key={item.key}
              {...choiceProps(item.index)}
              style={item.style}
              className="flex cursor-pointer items-center gap-2 rounded-sm px-2 aria-selected:bg-accent aria-selected:text-accent-foreground"
            >
              <span className="min-w-0 flex-1 truncate">{choice.label}</span>
              {choice.current && <Check className="size-3.5 shrink-0" />}
            </div>
          );
        })}
      </div>
    </div>
  );
}

import { useState, type ReactNode } from 'react';

import {
  closestCenter,
  DndContext,
  DragOverlay,
  pointerWithin,
  type CollisionDetection,
  type UniqueIdentifier,
} from '@dnd-kit/core';
import { horizontalListSortingStrategy, SortableContext } from '@dnd-kit/sortable';
import { ArrowLeftRight, Ban, Group } from 'lucide-react';

import { groupPanelId, useColumnDragAndDrop } from '@/components/data-grid/use-column-drag-and-drop';
import { cn } from '@/lib/utils';
import { useColumnReorder, type CoreTable } from '@istec/grid';

type DropAction = 'move' | 'group' | 'reject';

// Over the group panel the pointer decides, so a drop there groups even when another header is closer.
// Column group headers are no drop targets: being wide, they would win near column boundaries.
function collisionDetectionFor(headerIds: ReadonlySet<UniqueIdentifier>): CollisionDetection {
  return (args) => {
    const panel = pointerWithin({
      ...args,
      droppableContainers: args.droppableContainers.filter((container) => container.id === groupPanelId),
    });
    if (panel.length > 0) return panel;
    return closestCenter({
      ...args,
      droppableContainers: args.droppableContainers.filter((container) => headerIds.has(container.id)),
    });
  };
}

/** Wraps the header and the group panel, so a header dragged into the panel groups by its column. */
export function ColumnReorder<TData extends object>({
  table,
  children,
}: {
  table: CoreTable<TData>;
  children: ReactNode;
}) {
  const reorder = useColumnReorder(table);
  const [dragging, setDragging] = useState<string>();
  const [overPanel, setOverPanel] = useState(false);

  const dragAndDrop = useColumnDragAndDrop(({ active, over }) => {
    if (!over) return;
    if (over.id === groupPanelId) reorder.groupBy(String(active.id));
    else table.moveColumn(String(active.id), String(over.id));
  });
  const action: DropAction =
    !overPanel || dragging === undefined ? 'move' : reorder.canGroupBy(dragging) ? 'group' : 'reject';

  return (
    <DndContext
      {...dragAndDrop}
      onDragStart={(event) => {
        dragAndDrop.onDragStart();
        setDragging(String(event.active.id));
      }}
      onDragOver={(event) => setOverPanel(event.over?.id === groupPanelId)}
      onDragCancel={() => {
        dragAndDrop.onDragCancel();
        setDragging(undefined);
        setOverPanel(false);
      }}
      onDragEnd={(event) => {
        setDragging(undefined);
        setOverPanel(false);
        dragAndDrop.onDragEnd(event);
      }}
      collisionDetection={collisionDetectionFor(new Set(reorder.headerIds))}
    >
      <SortableContext items={reorder.headerIds} strategy={horizontalListSortingStrategy}>
        {children}
      </SortableContext>
      <DragOverlay dropAnimation={null}>
        {dragging !== undefined && (
          <div
            className={cn(
              'flex w-fit items-center gap-1.5 rounded-md border bg-popover px-2 py-1 text-xs font-medium shadow-md [&_svg]:size-3.5',
              action === 'reject' && 'border-destructive/50'
            )}
          >
            {action === 'move' && <ArrowLeftRight className="text-muted-foreground" />}
            {action === 'group' && <Group className="text-primary" />}
            {action === 'reject' && <Ban className="text-destructive" />}
            {reorder.label(dragging)}
          </div>
        )}
      </DragOverlay>
    </DndContext>
  );
}

import type { CSSProperties, ReactNode } from 'react';

import { cn } from '@/lib/utils';
import { useColumnWidths, type CoreTable } from '@istec/grid';

/** Header, body and footer are separate tables that share these column widths. */
export function ColumnTable<TData extends object>({
  table,
  className,
  style,
  children,
}: {
  table: CoreTable<TData>;
  className?: string;
  style?: CSSProperties;
  children: ReactNode;
}) {
  const { width, columns } = useColumnWidths(table);

  return (
    <table
      className={cn('min-w-full table-fixed border-separate border-spacing-0', className)}
      style={{ width, ...style }}
    >
      <colgroup>
        {columns.map((column) =>
          column === 'filler' ? <col key="filler" /> : <col key={column.id} style={{ width: column.width }} />
        )}
      </colgroup>
      {children}
    </table>
  );
}

import type { ReactNode } from 'react';

import { LoaderCircle } from 'lucide-react';

import { DataRow, VirtualRows, type DataRowOptions } from '@/components/data-grid/body';
import { ColumnReorder } from '@/components/data-grid/column-reorder';
import { ColumnTable } from '@/components/data-grid/column-table';
import { FloatingFilterRow } from '@/components/data-grid/filters';
import { StatusBar, TotalsRow } from '@/components/data-grid/footer';
import { GroupPanel } from '@/components/data-grid/group-panel';
import { HeaderRows } from '@/components/data-grid/header';
import { ContextMenuEntries } from '@/components/data-grid/menu-entries';
import { messages } from '@/components/data-grid/messages';
import { ContextMenu, ContextMenuContent, ContextMenuTrigger } from '@/components/ui/context-menu';
import { cn } from '@/lib/utils';
import {
  useCellMenu,
  useGridView,
  type CoreTable,
  type GridCell,
  type GridInstance,
  type GridMenuSection,
} from '@istec/grid';

/** Changes a cell's context menu: adds the app's own entries, or leaves out or reorders the grid's. */
export type CellMenuSections<TData extends object> = (
  sections: GridMenuSection[],
  cell: GridCell<TData> | undefined
) => GridMenuSection[];

export interface DataGridProps<TData extends object> extends Omit<DataRowOptions<TData>, 'rowHeight'> {
  table: GridInstance<TData>;
  headerHeight?: number;
  rowHeight?: number;
  overscan?: number;
  /** Shown instead of the rows when none pass the filters. */
  noRows?: ReactNode;
  loading?: boolean;
  /** Adds a footer row with the totals of the aggregated columns. */
  showTotals?: boolean;
  /** Shows the row above the header that columns are dragged into to group by them. */
  showGroupPanel?: boolean;
  /** Shows a row under the header with a filter per column. */
  showFloatingFilters?: boolean;
  /** Shows the footer with the row counts. */
  showStatusBar?: boolean;
  /** Shown at the end of the status bar. */
  statusBar?: ReactNode;
  /** Changes the focused cell's context menu (a right click focuses first); it starts with copy and paste. */
  cellMenu?: CellMenuSections<TData>;
  'aria-label'?: string;
  className?: string;
}

export function DataGrid<TData extends object>({
  table,
  headerHeight = 36,
  rowHeight = 32,
  overscan = 10,
  noRows,
  loading,
  showTotals = false,
  showGroupPanel = true,
  showFloatingFilters = false,
  showStatusBar = true,
  statusBar,
  cellMenu,
  'aria-label': ariaLabel,
  className,
  ...rowEvents
}: DataGridProps<TData>) {
  const view = useGridView(table, { rowHeight, loading, showTotals, showGroupPanel });
  const rowOptions: DataRowOptions<TData> = { rowHeight, ...rowEvents };

  return (
    <table.AppTable>
      <div className={cn('flex min-h-0 flex-1 flex-col overflow-hidden rounded-md border text-xs', className)}>
        <ColumnReorder table={table}>
          {view.groupPanel && <GroupPanel table={table} />}
          <div
            {...view.gridProps}
            aria-label={ariaLabel}
            className="group/grid relative flex min-w-0 flex-1 flex-col overflow-hidden [--range-edge:color-mix(in_oklab,--theme(--color-primary)_40%,transparent)] focus-within:[--range-edge:--theme(--color-primary)]"
          >
            <div
              {...view.headerProps}
              className="scrollbar-gutter-stable overflow-hidden border-b bg-muted select-none"
            >
              <ColumnTable table={table}>
                <thead>
                  <HeaderRows table={table} headerHeight={headerHeight} />
                  {showFloatingFilters && <FloatingFilterRow table={table} height={rowHeight} />}
                </thead>
                {view.topRows.length > 0 && (
                  <tbody className="bg-background [&>tr:first-child>td]:border-t [&>tr:last-child>td]:border-b-0">
                    {view.topRows.map((row) => (
                      <DataRow key={row.id} row={row} {...rowOptions} />
                    ))}
                  </tbody>
                )}
              </ColumnTable>
            </div>
            <ContextMenu>
              <ContextMenuTrigger
                {...view.scrollProps}
                className="min-h-0 flex-1 scrollbar-gutter-stable overflow-auto outline-none"
              >
                <VirtualRows
                  table={table}
                  scrollElement={view.scrollElement}
                  overscan={overscan}
                  noRows={noRows}
                  {...rowOptions}
                />
              </ContextMenuTrigger>
              <ContextMenuContent className="w-56">
                <CellMenu table={table} customize={cellMenu} />
              </ContextMenuContent>
            </ContextMenu>
            {(view.bottomRows.length > 0 || view.totals) && (
              <div {...view.footerProps} className="scrollbar-gutter-stable overflow-hidden border-t">
                <ColumnTable table={table}>
                  <tbody className="[&>tr:last-child>td]:border-b-0">
                    {view.bottomRows.map((row) => (
                      <DataRow key={row.id} row={row} {...rowOptions} />
                    ))}
                    {view.totals && <TotalsRow table={table} rowHeight={rowHeight} />}
                  </tbody>
                </ColumnTable>
              </div>
            )}
            {view.busy && (
              <div className="absolute inset-0 z-30 flex items-center justify-center gap-2 bg-background/60 text-muted-foreground">
                <LoaderCircle className="size-4 animate-spin" />
                {messages.loading}
              </div>
            )}
          </div>
        </ColumnReorder>
        {showStatusBar && <StatusBar table={table}>{statusBar}</StatusBar>}
      </div>
    </table.AppTable>
  );
}

// Rendered only while the menu is open; a right click focuses its cell first.
function CellMenu<TData extends object>({
  table,
  customize,
}: {
  table: CoreTable<TData>;
  customize?: CellMenuSections<TData>;
}) {
  const { cell, sections } = useCellMenu(table);
  return <ContextMenuEntries sections={customize ? customize(sections, cell) : sections} />;
}

import { useId, useState } from 'react';

import { ListFilter, Search, X } from 'lucide-react';

import { filterSummaryText, messages } from '@/components/data-grid/messages';
import { pinnedClassName } from '@/components/data-grid/styles';
import { Button } from '@/components/ui/button';
import { Checkbox } from '@/components/ui/checkbox';
import { Input } from '@/components/ui/input';
import { InputGroup, InputGroupAddon, InputGroupInput } from '@/components/ui/input-group';
import { Label } from '@/components/ui/label';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { cn } from '@/lib/utils';
import {
  columnLabel,
  textCodec,
  useFilterInput,
  useFloatingFilter,
  useHeaderRows,
  useRangeFilter,
  useSetFilter,
  useVirtualList,
  type CoreTable,
  type FilterKind,
  type GridColumn,
  type SetFilterOption,
} from '@istec/grid';

export function FilterEditor<TData extends object>({ column, kind }: { column: GridColumn<TData>; kind: FilterKind }) {
  if (kind === 'text') return <TextFilter column={column} />;
  if (kind === 'set') return <SetFilter column={column} />;
  return <RangeFilter column={column} type={kind} />;
}

function ClearFilterButton({ enabled, onClear }: { enabled: boolean; onClear: () => void }) {
  return (
    <Button variant="ghost" size="sm" className="self-end" disabled={!enabled} onClick={onClear}>
      <X />
      {messages.clearFilter}
    </Button>
  );
}

function TextFilter<TData extends object>({ column }: { column: GridColumn<TData> }) {
  const filter = useFilterInput(column, textCodec);

  return (
    <>
      <Input
        aria-label={messages.textFilter}
        placeholder={messages.textFilter}
        value={filter.text}
        onChange={(event) => filter.change(event.target.value)}
      />
      <ClearFilterButton enabled={filter.canClear} onClear={filter.clear} />
    </>
  );
}

function RangeFilter<TData extends object>({ column, type }: { column: GridColumn<TData>; type: 'number' | 'date' }) {
  const filter = useRangeFilter(column, type);
  const id = useId();
  const labels = type === 'number' ? messages.numberBounds : messages.dateBounds;

  return (
    <>
      <div className="grid grid-cols-[auto_1fr] items-center gap-x-2 gap-y-1.5">
        {([0, 1] as const).map((bound) => (
          <div key={bound} className="contents">
            <Label htmlFor={`${id}-${bound}`}>{labels[bound]}</Label>
            <Input
              id={`${id}-${bound}`}
              type={type}
              value={filter.text[bound]}
              placeholder={filter.placeholders?.[bound]}
              onChange={(event) =>
                filter.change(bound === 0 ? [event.target.value, filter.text[1]] : [filter.text[0], event.target.value])
              }
            />
          </div>
        ))}
      </div>
      <ClearFilterButton enabled={filter.canClear} onClear={filter.clear} />
    </>
  );
}

function SetFilter<TData extends object>({ column }: { column: GridColumn<TData> }) {
  const filter = useSetFilter(column);

  return (
    <>
      <InputGroup>
        <InputGroupAddon>
          <Search />
        </InputGroupAddon>
        <InputGroupInput
          type="search"
          aria-label={messages.searchValues}
          placeholder={messages.searchValues}
          value={filter.query}
          onChange={(event) => filter.setQuery(event.target.value)}
          onKeyDown={(event) => {
            if (event.key === 'Enter') filter.keepFound();
          }}
        />
      </InputGroup>
      <div className="flex flex-col gap-0.5">
        <label className="flex h-8 cursor-pointer items-center gap-2 rounded-sm border-b px-2 font-medium hover:bg-muted">
          <Checkbox
            checked={filter.selectAll.checked}
            indeterminate={filter.selectAll.indeterminate}
            disabled={filter.selectAll.disabled}
            onCheckedChange={() => filter.toggleAll(!filter.selectAll.checked)}
          />
          {messages.selectAllValues}
        </label>
        <SetFilterList
          options={filter.options}
          isChecked={filter.isChecked}
          onToggle={(option, checked) => filter.toggle([option], checked)}
        />
      </div>
      <ClearFilterButton enabled={filter.canClear} onClear={filter.clear} />
    </>
  );
}

function SetFilterList({
  options,
  isChecked,
  onToggle,
}: {
  options: SetFilterOption[];
  isChecked: (option: SetFilterOption) => boolean;
  onToggle: (option: SetFilterOption, checked: boolean) => void;
}) {
  const list = useVirtualList(options.length, { itemHeight: 30, maxHeight: 320 });

  return (
    <div {...list.scrollProps}>
      <div style={list.contentStyle}>
        {list.items.map((item) => {
          const option = options[item.index];
          if (!option) return null;
          return (
            <label
              key={option.key}
              style={item.style}
              className="flex cursor-pointer items-center gap-2 rounded-sm px-2 hover:bg-muted"
            >
              <Checkbox checked={isChecked(option)} onCheckedChange={(checked) => onToggle(option, checked)} />
              <span className="min-w-0 flex-1 truncate">{option.blank ? messages.blank : option.label}</span>
              <span className="text-muted-foreground tabular-nums">{option.count}</span>
            </label>
          );
        })}
      </div>
    </div>
  );
}

const fieldClassName =
  'h-6 w-full min-w-0 rounded-sm border bg-background px-1.5 font-normal outline-none focus-visible:ring-1 focus-visible:ring-primary aria-invalid:border-destructive';

export function FloatingFilterRow<TData extends object>({
  table,
  height,
}: {
  table: CoreTable<TData>;
  height: number;
}) {
  const leafRow = useHeaderRows(table).at(-1);
  if (!leafRow) return null;

  return (
    <tr>
      {leafRow.slots.map((slot) =>
        slot === 'filler' ? (
          <th key="filler" aria-hidden className="border-t" />
        ) : (
          <th
            key={slot.header.id}
            style={{ height, ...slot.style }}
            className={cn('border-t px-1 align-middle', pinnedClassName(slot.region, slot.edge), 'bg-muted')}
          >
            <FloatingFilter column={slot.header.column} />
          </th>
        )
      )}
    </tr>
  );
}

function FloatingFilter<TData extends object>({ column }: { column: GridColumn<TData> }) {
  const filter = useFloatingFilter(column);
  const [open, setOpen] = useState(false);
  if (filter.mode === 'none' || !filter.filter) return null;
  const label = `${messages.filter}: ${columnLabel(column)}`;

  if (filter.mode === 'typed') {
    return (
      <input
        type="search"
        aria-label={label}
        aria-invalid={filter.invalid || undefined}
        title={filter.filter === 'number' ? messages.numberHint : undefined}
        value={filter.text}
        onChange={(event) => filter.change(event.target.value)}
        className={fieldClassName}
      />
    );
  }

  const summary = filterSummaryText(filter.summary);
  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger
        aria-label={label}
        title={summary || undefined}
        className={cn(fieldClassName, 'flex cursor-pointer items-center gap-1 text-left')}
      >
        <span className="min-w-0 flex-1 truncate">{summary}</span>
        <ListFilter className={cn('size-3.5 shrink-0', summary === '' ? 'text-muted-foreground' : 'text-primary')} />
      </PopoverTrigger>
      <PopoverContent align="start" className="w-64 gap-2 p-2">
        <FilterEditor column={column} kind={filter.filter} />
      </PopoverContent>
    </Popover>
  );
}

