import { createContext, use, useState } from 'react';

import { closestCenter, DndContext, DragOverlay, useDndContext, useDroppable } from '@dnd-kit/core';
import { restrictToHorizontalAxis } from '@dnd-kit/modifiers';
import { horizontalListSortingStrategy, SortableContext, useSortable } from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';
import { ChevronRight, GripVertical, Group, X } from 'lucide-react';

import { SortIndicator } from '@/components/data-grid/header';
import { messages } from '@/components/data-grid/messages';
import { barClassName } from '@/components/data-grid/styles';
import { ExpandCollapseButtons } from '@/components/data-grid/toolbar';
import { groupPanelId, useColumnDragAndDrop } from '@/components/data-grid/use-column-drag-and-drop';
import { cn } from '@/lib/utils';
import { useColumnReorder, useGroupPanel, type CoreTable, type GroupChip } from '@istec/grid';

/** Must sit inside `ColumnReorder`: header columns are dragged into it to group by them. */
export function GroupPanel<TData extends object>({ table }: { table: CoreTable<TData> }) {
  const chips = useGroupPanel(table);
  const reorder = useColumnReorder(table);
  const { setNodeRef, isOver } = useDroppable({ id: groupPanelId });
  const { active } = useDndContext();
  const dragged = active !== null && reorder.headerIds.includes(String(active.id)) ? String(active.id) : undefined;
  const accepts = dragged !== undefined && reorder.canGroupBy(dragged);
  const pending = isOver && accepts && dragged !== undefined ? reorder.label(dragged) : undefined;

  return (
    <div
      ref={setNodeRef}
      role="toolbar"
      aria-label={messages.groupPanel}
      className={cn(
        barClassName,
        'gap-1 border-b transition-colors select-none',
        isOver && accepts && 'bg-accent',
        isOver && dragged !== undefined && !accepts && 'bg-destructive/10'
      )}
    >
      <Group className="size-3.5 shrink-0 text-muted-foreground" />
      {chips.length === 0 && pending === undefined ? (
        <span className="px-1 text-muted-foreground">{messages.groupPanelPlaceholder}</span>
      ) : (
        <GroupChips table={table} chips={chips} pending={pending} />
      )}
      <ExpandCollapseButtons table={table} size="sm" className="ml-auto" />
    </div>
  );
}

// While the levels are reordered, arrows between chips would point between the wrong ones, so they hide.
const ReorderingContext = createContext(false);

// `pending` is a header column dragged over the panel, shown as the level it would add.
function GroupChips<TData extends object>({
  table,
  chips: levels,
  pending,
}: {
  table: CoreTable<TData>;
  chips: GroupChip<TData>[];
  pending?: string;
}) {
  const [dragging, setDragging] = useState<string>();
  // The grouping arrives a render after the drop but dnd-kit drops its transforms at once; keeping the dropped
  // order meanwhile stops the chips from showing the old order for a frame and sliding back.
  const [dropped, setDropped] = useState<{ order: string[]; over: string }>();
  const grouping = levels.map((chip) => chip.column.id);
  const groupingKey = grouping.join('\n');
  if (dropped && dropped.over !== groupingKey) setDropped(undefined);
  const ids = dropped?.order ?? grouping;
  const chips = ids.flatMap((id) => levels.filter((chip) => chip.column.id === id));
  const dragAndDrop = useColumnDragAndDrop(({ active, over }) => {
    if (!over || active.id === over.id) return;
    const from = ids.indexOf(String(active.id));
    const to = ids.indexOf(String(over.id));
    setDropped({ order: ids.toSpliced(from, 1).toSpliced(to, 0, String(active.id)), over: groupingKey });
    table.moveGrouping(from, to);
  });
  const draggedChip = chips.find((chip) => chip.column.id === dragging);

  return (
    <div className="flex items-center gap-5 pl-1">
      <DndContext
        {...dragAndDrop}
        onDragStart={(event) => {
          dragAndDrop.onDragStart();
          setDragging(String(event.active.id));
        }}
        onDragCancel={() => {
          dragAndDrop.onDragCancel();
          setDragging(undefined);
        }}
        onDragEnd={(event) => {
          setDragging(undefined);
          dragAndDrop.onDragEnd(event);
        }}
        collisionDetection={closestCenter}
        modifiers={[restrictToHorizontalAxis]}
      >
        <ReorderingContext value={dragging !== undefined}>
          <SortableContext items={ids} strategy={horizontalListSortingStrategy}>
            {chips.map((chip, index) => (
              <SortableChip key={chip.column.id} chip={chip} first={index === 0} />
            ))}
            {pending !== undefined && (
              <div className="relative flex items-center">
                {chips.length > 0 && <LevelArrow />}
                <span className="flex h-6 items-center gap-1 rounded-md border border-dashed border-primary/60 bg-background/60 px-2 font-medium text-muted-foreground">
                  <Group className="size-3.5 text-primary" />
                  {pending}
                </span>
              </div>
            )}
          </SortableContext>
        </ReorderingContext>
        <DragOverlay dropAnimation={null}>
          {draggedChip && (
            <span className="flex h-6 w-fit items-center gap-1 rounded-md border bg-background px-2 font-medium shadow-md">
              <GripVertical className="size-3.5 text-muted-foreground" />
              {draggedChip.label}
            </span>
          )}
        </DragOverlay>
      </DndContext>
    </div>
  );
}

// Sits in the gap, outside the chip's width, so the widths the drag measured stay true.
function LevelArrow({ hidden = false }: { hidden?: boolean }) {
  return (
    <ChevronRight
      className={cn(
        'absolute top-1/2 -left-[17px] size-3.5 -translate-y-1/2 text-muted-foreground',
        hidden && 'invisible'
      )}
    />
  );
}

function SortableChip<TData extends object>({ chip, first }: { chip: GroupChip<TData>; first: boolean }) {
  const reordering = use(ReorderingContext);
  const { attributes, listeners, setNodeRef, setActivatorNodeRef, transform, transition, isDragging } = useSortable({
    id: chip.column.id,
  });

  return (
    <div
      ref={setNodeRef}
      style={{ transform: CSS.Translate.toString(transform), transition }}
      className="relative flex items-center"
    >
      {!first && <LevelArrow hidden={reordering} />}
      <span
        className={cn(
          'flex h-6 items-center rounded-md border bg-background pr-0.5 font-medium shadow-xs',
          isDragging && 'opacity-40'
        )}
      >
        <button
          type="button"
          ref={setActivatorNodeRef}
          aria-label={messages.moveGroupLevel}
          {...attributes}
          {...listeners}
          className="flex h-full cursor-grab touch-none items-center rounded-l-md px-0.5 text-muted-foreground hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none active:cursor-grabbing [&_svg]:size-3.5"
        >
          <GripVertical />
        </button>
        <button
          type="button"
          disabled={!chip.canSort}
          onClick={chip.toggleSorting}
          className="flex h-full items-center gap-1 pr-1 enabled:cursor-pointer [&_svg]:size-3.5"
        >
          {chip.label}
          <SortIndicator sorted={chip.sorted} position={chip.sortPosition} />
        </button>
        <button
          type="button"
          aria-label={messages.removeGrouping}
          onClick={chip.remove}
          className="rounded-sm p-0.5 text-muted-foreground hover:bg-muted-foreground/20 hover:text-foreground"
        >
          <X className="size-3" />
        </button>
      </span>
    </div>
  );
}

import { useState, type CSSProperties, type ReactNode } from 'react';

import { useSortable } from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';
import { FlexRender, type SortDirection } from '@tanstack/react-table';
import { ArrowDown, ArrowUp, EllipsisVertical, ListFilter } from 'lucide-react';

import { FilterEditor } from '@/components/data-grid/filters';
import { ContextMenuEntries, DropdownMenuEntries } from '@/components/data-grid/menu-entries';
import { messages } from '@/components/data-grid/messages';
import { flexAlign, pinnedClassName } from '@/components/data-grid/styles';
import { ContextMenu, ContextMenuContent, ContextMenuTrigger } from '@/components/ui/context-menu';
import { DropdownMenu, DropdownMenuContent, DropdownMenuTrigger } from '@/components/ui/dropdown-menu';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { cn } from '@/lib/utils';
import {
  useColumnMenu,
  useColumnResizer,
  useHeaderCell,
  useHeaderRows,
  type CoreTable,
  type GridColumn,
  type GridHeader,
  type HeaderSlot,
} from '@istec/grid';

export function HeaderRows<TData extends object>({
  table,
  headerHeight,
}: {
  table: CoreTable<TData>;
  headerHeight: number;
}) {
  return useHeaderRows(table).map((row) => (
    <tr key={row.id}>
      {row.slots.map((slot) =>
        slot === 'filler' ? (
          <th key="filler" aria-hidden />
        ) : (
          <HeaderCell key={slot.header.id} slot={slot} height={headerHeight} />
        )
      )}
    </tr>
  ));
}

const iconButtonClassName =
  'flex size-5 shrink-0 cursor-pointer items-center justify-center rounded-sm text-muted-foreground outline-none hover:bg-foreground/10 hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/50 aria-expanded:bg-foreground/10 aria-expanded:text-foreground [&_svg]:size-3.5';

// Keeps a press on a button inside the header from starting a column drag.
const stopDrag = { onPointerDown: (event: { stopPropagation: () => void }) => event.stopPropagation() };

function HeaderCell<TData extends object>({ slot, height }: { slot: HeaderSlot<TData>; height: number }) {
  const model = useHeaderCell(slot);
  const { header, region, edge } = slot;
  const { attributes, listeners, setNodeRef, setActivatorNodeRef, transform, transition, isDragging } = useSortable({
    id: header.id,
    disabled: !model.reorderable,
  });
  // The cell keeps its columnheader role; dnd-kit's role="button" would hide it from screen readers.
  const { role: _role, ...dragAttributes } = attributes;
  const [cell, setCell] = useState<HTMLTableCellElement | null>(null);
  const [filterOpen, setFilterOpen] = useState(false);
  // Only the sideways move shows; dragged up into the group panel, the column follows as the drag overlay.
  const style: CSSProperties = {
    height,
    ...model.cellProps.style,
    transform: CSS.Translate.toString(transform && { ...transform, y: 0 }),
    transition,
  };

  return (
    <th
      {...model.cellProps}
      {...(model.reorderable ? { ...dragAttributes, ...listeners } : {})}
      ref={(node) => {
        setNodeRef(node);
        // Keys pressed on the buttons inside bubble up here; only keys on the cell itself start a drag.
        setActivatorNodeRef(node);
        setCell(node);
      }}
      style={style}
      className={cn(
        'group relative text-left align-middle font-medium whitespace-nowrap text-foreground',
        model.kind === 'group' && 'border-b',
        // Pinned headers keep the header's background over the pinned cells' one.
        pinnedClassName(region, edge),
        'bg-muted',
        model.reorderable &&
          'outline-none focus-visible:outline-1 focus-visible:-outline-offset-1 focus-visible:outline-primary focus-visible:outline-solid',
        isDragging && 'z-20 bg-background opacity-90 shadow-sm',
        model.className
      )}
    >
      {model.kind === 'group' ? (
        <div className="flex h-full items-center px-2">
          <span className="truncate">
            <FlexRender header={header} />
          </span>
        </div>
      ) : model.kind === 'column' ? (
        <Popover open={filterOpen} onOpenChange={setFilterOpen}>
          <ColumnContent
            column={header.column}
            enabled={model.hasMenu}
            onFilter={() => setFilterOpen(true)}
            className={cn('flex h-full items-center gap-1 px-2', flexAlign[model.align])}
          >
            <HeaderLabel slot={slot} reverse={model.align === 'end'} groupColumn={model.groupColumn} />
            {model.filter && model.filtered && (
              <PopoverTrigger
                {...stopDrag}
                aria-label={messages.filter}
                className={cn(iconButtonClassName, 'bg-primary/15 text-primary hover:bg-primary/25 hover:text-primary')}
              >
                <ListFilter />
              </PopoverTrigger>
            )}
            {model.showMenuButton && <ColumnMenuButton column={header.column} onFilter={() => setFilterOpen(true)} />}
          </ColumnContent>
          {model.filter && (
            <PopoverContent anchor={cell} align="start" className="w-64 gap-2 p-2" {...stopDrag}>
              <FilterEditor column={header.column} kind={model.filter} />
            </PopoverContent>
          )}
        </Popover>
      ) : null}
      <ColumnResizer header={header} />
    </th>
  );
}

function HeaderLabel<TData extends object>({
  slot: { header, toggleSorting, sorted, sortPosition },
  reverse,
  groupColumn,
}: {
  slot: HeaderSlot<TData>;
  reverse: boolean;
  groupColumn: boolean;
}) {
  const label = <span className="truncate">{groupColumn ? messages.groupColumn : <FlexRender header={header} />}</span>;

  const className = cn(
    'flex min-w-0 flex-1 items-center gap-1 text-left [&_svg]:size-3.5 [&_svg]:shrink-0',
    reverse && 'flex-row-reverse text-right'
  );
  if (!toggleSorting) return <span className={className}>{label}</span>;

  return (
    <button type="button" onClick={toggleSorting} className={cn(className, 'cursor-pointer')}>
      {label}
      <SortIndicator sorted={sorted} position={sortPosition} />
    </button>
  );
}

export function SortIndicator({ sorted, position }: { sorted: false | SortDirection; position: number }) {
  if (!sorted) return null;

  return (
    <span className="flex items-center [&_svg]:size-3.5">
      {sorted === 'asc' ? <ArrowUp /> : <ArrowDown />}
      {position > 0 && <span className="text-[10px] leading-none text-muted-foreground tabular-nums">{position}</span>}
    </span>
  );
}

function ColumnContent<TData extends object>({
  column,
  enabled,
  onFilter,
  className,
  children,
}: {
  column: GridColumn<TData>;
  enabled: boolean;
  onFilter: () => void;
  className: string;
  children: ReactNode;
}) {
  if (!enabled) return <div className={className}>{children}</div>;

  return (
    <ContextMenu>
      <ContextMenuTrigger className={className}>{children}</ContextMenuTrigger>
      <ContextMenuContent className="w-52" {...stopDrag}>
        <ColumnMenuEntries column={column} onFilter={onFilter} variant="context" />
      </ContextMenuContent>
    </ContextMenu>
  );
}

function ColumnMenuButton<TData extends object>({
  column,
  onFilter,
}: {
  column: GridColumn<TData>;
  onFilter: () => void;
}) {
  return (
    <DropdownMenu>
      <DropdownMenuTrigger {...stopDrag} aria-label={messages.columnMenu} className={iconButtonClassName}>
        <EllipsisVertical />
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end" className="w-52" {...stopDrag}>
        <ColumnMenuEntries column={column} onFilter={onFilter} variant="dropdown" />
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

// Rendered only while the menu is open, and kept current while it is.
function ColumnMenuEntries<TData extends object>({
  column,
  onFilter,
  variant,
}: {
  column: GridColumn<TData>;
  onFilter: () => void;
  variant: 'context' | 'dropdown';
}) {
  const sections = useColumnMenu(column, { onFilter });
  return variant === 'context' ? (
    <ContextMenuEntries sections={sections} />
  ) : (
    <DropdownMenuEntries sections={sections} />
  );
}

function ColumnResizer<TData extends object>({ header }: { header: GridHeader<TData> }) {
  const { canResize, resizing, handleProps } = useColumnResizer(header);
  const line = (
    <div
      className={cn(
        'h-1/2 w-px bg-border transition-[height]',
        resizing ? 'h-full bg-primary' : 'group-hover/divider:h-full group-hover/divider:bg-primary/60'
      )}
    />
  );

  if (!canResize) return <div className="absolute top-0 -right-px flex h-full items-center">{line}</div>;

  return (
    <div
      {...handleProps}
      {...stopDrag}
      className="group/divider absolute top-0 -right-1.5 z-10 flex h-full w-3 cursor-col-resize touch-none items-center justify-center select-none"
    >
      {line}
    </div>
  );
}

