// Plain characters of one font: combined marks such as x̃ or #≠ mix fallback fonts and sit askew.
export const aggregationSymbols: Record<AggregationName, string> = {
  sum: 'Σ',
  mean: 'Ø',
  median: 'med',
  min: 'min',
  max: 'max',
  count: '#',
  uniqueCount: 'uniq',
};

export const aggregationName = (aggregation: AggregationName) => menuLabels[`aggregation.${aggregation}`];

export function statusTexts(status: GridStatus, format: (value: number) => string) {
  return {
    rows:
      status.shownRows === status.rows
        ? `${format(status.rows)} rows`
        : `${format(status.shownRows)} of ${format(status.rows)} rows`,
    groups: status.groups > 0 ? `${format(status.groups)} groups` : undefined,
    selected: status.selectedRows > 0 ? `${format(status.selectedRows)} selected` : undefined,
    cells: status.cells && `${format(status.cells.count)} cells`,
  };
}

export function editorErrorText(error: CellEditorError): string {
  if (error.type === 'rule') return error.message;
  if (error.type === 'number') return 'Not a valid number';
  if (error.type === 'date') return 'Not a valid date';
  return 'Not a valid value';
}

// As AG Grid's floating filters show it: `a – b`, `≥ a`, `≤ b`, or `(3) a, b, c`.
export function filterSummaryText(summary: FilterSummary | undefined): string {
  if (!summary) return '';
  if (summary.kind === 'text') return summary.text;
  if (summary.kind === 'range') {
    const { from, to } = summary;
    if (from !== undefined && to !== undefined) return from === to ? from : `${from} – ${to}`;
    return from !== undefined ? `≥ ${from}` : `≤ ${to ?? ''}`;
  }
  const values = summary.blank ? [messages.blank, ...summary.values] : summary.values;
  if (values.length === 0) return messages.noneSelected;
  return values.length <= 2 ? values.join(', ') : `(${values.length}) ${values.join(', ')}`;
}

import { useRef } from 'react';

import { messages } from '@/components/data-grid/messages';
import { Checkbox } from '@/components/ui/checkbox';
import { useRowSelect, useSelectAll, type CoreTable, type GridRow } from '@istec/grid';

export function SelectAllCheckbox<TData extends object>({ table }: { table: CoreTable<TData> }) {
  const select = useSelectAll(table);
  return (
    <span className="flex justify-center">
      <Checkbox
        aria-label={messages.selectAll}
        checked={select.checked}
        indeterminate={select.indeterminate}
        onCheckedChange={(next) => select.toggle(next)}
      />
    </span>
  );
}

/** A row's checkbox; with Shift held, it selects the rows between the last one toggled and this one. */
export function RowCheckbox<TData extends object>({ row }: { row: GridRow<TData> }) {
  const select = useRowSelect(row);
  const shift = useRef(false);

  return (
    <span className="flex justify-center">
      <Checkbox
        aria-label={messages.selectRow}
        checked={select.checked}
        indeterminate={select.indeterminate}
        disabled={select.disabled}
        onClick={(event) => {
          event.stopPropagation();
          shift.current = event.shiftKey;
        }}
        onCheckedChange={(next) => select.toggle(next, shift.current)}
      />
    </span>
  );
}

import { RowCheckbox, SelectAllCheckbox } from '@/components/data-grid/selection-checkboxes';
import type { GridColumnDef } from '@istec/grid';

/** The checkbox column; pin it with `columnPinning: { start: ['select'] }`. */
export function selectionColumn<TData extends object>(): GridColumnDef<TData> {
  return {
    id: 'select',
    size: 36,
    minSize: 36,
    enableSorting: false,
    enableResizing: false,
    enableHiding: false,
    enableGrouping: false,
    enableColumnFilter: false,
    enableGlobalFilter: false,
    meta: { lockPosition: true, menu: false, align: 'center' },
    header: ({ table }) => <SelectAllCheckbox table={table} />,
    cell: ({ row }) => <RowCheckbox row={row} />,
  };
}

import { cn } from '@/lib/utils';
import type { CellLook, ColumnAlign, Region } from '@istec/grid';

export const barClassName = 'flex min-h-8 items-center bg-muted/40 px-2 py-0.5';

// The style is set explicitly: the cell's outline-none leaves a `none` style that a bare outline would inherit.
export const focusOutlineClassName =
  'group-focus-within/grid:outline-1 group-focus-within/grid:outline-solid group-focus-within/grid:-outline-offset-1 group-focus-within/grid:outline-primary';

export const textAlign: Record<ColumnAlign, string> = {
  start: 'text-left',
  center: 'text-center',
  end: 'text-right',
};

export const flexAlign: Record<ColumnAlign, string> = {
  start: 'justify-start',
  center: 'justify-center',
  end: 'justify-end',
};

export function pinnedClassName(region: Region, edge: boolean) {
  if (region === 'center') return undefined;
  return cn('bg-background', edge && (region === 'start' ? 'border-r' : 'border-l'));
}

// `--range-edge` is set on the grid.
export function rangeShadow({ top, right, bottom, left }: CellLook): string | undefined {
  const sides = [
    top && 'inset 0 1px 0 var(--range-edge)',
    right && 'inset -1px 0 0 var(--range-edge)',
    bottom && 'inset 0 -1px 0 var(--range-edge)',
    left && 'inset 1px 0 0 var(--range-edge)',
  ].filter(Boolean);
  return sides.length > 0 ? sides.join(', ') : undefined;
}

import { ChevronsDownUp, ChevronsUpDown, Columns3, Download, FilterX, Search } from 'lucide-react';

